# Analysis-only fixture oracle. No network, Freya calls, credentials or file writes.
import copy
import json
import re
import sys
from datetime import date, datetime, timedelta
from decimal import Decimal
from pathlib import Path

def check(ok, message):
    if not ok:
        raise AssertionError(message)

def dec(value):
    return Decimal(str(value))

def business(day, config):
    return day.weekday() in config["business_days"] and day.isoformat() not in config["holidays"]

def next_business(day, config):
    day += timedelta(days=1)
    while not business(day, config):
        day += timedelta(days=1)
    return day

def validate(case, trace, config):
    state = case["initial_state"]
    identity = bool(state["identity_verified"])
    dob_passed = identity
    wrong_left = 3
    now = datetime.fromisoformat(case["call_variables"]["now"])
    products = {p["product_id"]: p for p in state["products"]}
    order = list(products)
    pending = None
    seen_ids = set()
    last_readback = None
    confirmed = {}
    recorded = {}
    attempts = {}
    dispositions = {}
    notes = []
    callbacks = []
    transfers = []
    close = None
    close_count = 0
    terminal = False
    input_closed = False
    goodbye = False
    transfer_requested = ""
    calls = []
    speech = []
    for index, e in enumerate(trace):
        kind = e["kind"]
        if kind == "user":
            check(not input_closed, "user input admitted after the asserted finalization boundary")
        elif kind == "speech":
            text = e["text"]
            speech.append(text)
            if not identity:
                check(not re.search(r"\b(collections|debt|payment|credit card|personal loan|car loan)\b", text, re.I),
                      "pre-verification disclosure")
            if e.get("recorded_product"):
                check(e["recorded_product"] in recorded, "recorded-success speech without receipt")
            goodbye = goodbye or e.get("goodbye", False)
        elif kind == "correction":
            confirmed = {}
            last_readback = None
        elif kind == "readback":
            check(not pending, "readback changed while effect in flight")
            check(bool(e["terms"]), "empty readback")
            check(all(t["product_id"] in products for t in e["terms"]), "unknown product in readback")
            check([t["product_id"] for t in e["terms"]] ==
                  [p for p in order if p in {t["product_id"] for t in e["terms"]}], "readback order")
            last_readback = e
            confirmed = {}
        elif kind == "confirm":
            check(last_readback is not None and e["revision"] == last_readback["revision"], "stale confirmation")
            confirmed = {t["product_id"]: t for t in last_readback["terms"]} if e["accepted"] else {}
        elif kind == "buffer_note":
            p = e["product_id"]
            check(p in products and p not in recorded, "invalid disposition product")
            check(e["reason"] in ("paid","refused","hardship","dispute","service_error"), "invalid note reason")
            if e["reason"] == "service_error":
                check(attempts.get(p, 0) == 2, "service_error before two definite failures")
            dispositions[p] = e["reason"]
            confirmed.pop(p, None)
        elif kind == "transfer_requested":
            check(not input_closed, "late transfer request exposes admission-boundary failure")
            transfer_requested = e["reason"]
            confirmed = {}
        elif kind == "finalize":
            check(not pending, "finalize with pending effect")
            check(not transfer_requested, "finalize ignored transfer")
            check(e.get("input_closed") is True, "note barrier not established")
            check(all(p in recorded or p in dispositions for p in order), "unresolved product at finalize")
            terminal = True
            input_closed = True
        elif kind == "call":
            check(close_count == 0, "bank action after close")
            check(pending is None, "second effect while prior result is unknown")
            check(e["action_id"] not in seen_ids, "replayed action id")
            seen_ids.add(e["action_id"])
            tool, args = e["tool"], e["args"]
            check(args["customer_id"] == case["call_variables"]["customer_id"], "customer id changed")
            check(tool not in case.get("forbidden_tools", []), "forbidden capability: " + tool)
            if tool == "verify_identity":
                check(wrong_left > 0, "identity attempts exhausted")
                expected_field = "phone_last4" if dob_passed else "date_of_birth"
                check(args["field"] == expected_field, "security fields out of order")
                if expected_field == "date_of_birth":
                    date.fromisoformat(args["answer"])
                else:
                    check(bool(re.fullmatch(r"[0-9]{4}", args["answer"])), "invalid phone suffix")
            elif tool == "get_account":
                check(identity, "get_account without trusted verification")
            elif tool == "create_promise":
                p = args["product_id"]
                check(identity and p in products, "promise identity/product gate")
                check(not terminal and not transfer_requested, "promise after terminal intent")
                check(p not in recorded, "duplicate recorded promise")
                check(p in confirmed, "promise without current confirmation")
                t = confirmed[p]
                check(dec(args["amount"]) == dec(t["amount"]) and args["date"] == t["date"],
                      "terms differ from confirmed readback")
                prod = products[p]
                amount = dec(args["amount"])
                day = date.fromisoformat(args["date"])
                check(amount.is_finite() and dec(prod["floor"]) <= amount <= dec(prod["past_due"]),
                      "amount outside product bounds")
                check(now.date() <= day <= date.fromisoformat(prod["deadline"]) and business(day, config),
                      "date violates injected calendar/deadline")
                pending_products = [p0 for p0 in order if p0 in confirmed and p0 not in recorded]
                check(pending_products and p == pending_products[0], "product dispatch order")
                attempts[p] = attempts.get(p, 0) + 1
                check(attempts[p] <= 2, "create retry budget exceeded")
            elif tool == "schedule_callback":
                when = datetime.fromisoformat(args["date"] + "T" + args["time"])
                check(when > now, "callback not future")
                check(when.date() in (now.date(), next_business(now.date(), config)), "callback wrong day")
                check("10:00" <= args["time"] <= "19:00", "callback outside window")
            elif tool == "add_note":
                p = args["product_id"]
                check(case["brief"] == "B" and terminal and input_closed, "eager note before valid barrier")
                check(not transfers and not transfer_requested, "note on transfer call")
                check(p not in recorded and dispositions.get(p) == args["reason"], "invalid note")
                todo = [p0 for p0 in order if p0 in dispositions and p0 not in {n["product_id"] for n in notes}]
                check(todo and todo[0] == p, "note order/duplicate")
            elif tool == "transfer_to_agent":
                check(not notes, "transfer after an irreversible note")
                expected_queue = {"human":"general","support":"support","restructuring":"restructuring"}.get(transfer_requested)
                check(args["queue"] == expected_queue, "transfer not source-authorized")
                check(not transfers, "duplicate transfer")
            elif tool == "close_call":
                check(goodbye, "goodbye must precede close dispatch")
                close_count += 1
                if transfers:
                    expected = {"outcome":"transferred","reason":transfer_requested}
                    check(not notes, "transfer trace contains notes")
                elif order:
                    check(terminal, "missing non-transfer finalization")
                    check(all(p in recorded or p in dispositions for p in order), "missing product disposition")
                    if case["brief"] == "B":
                        check({n["product_id"] for n in notes} == set(dispositions), "unflushed notes")
                    if recorded:
                        expected = {"outcome":"promise"}
                    elif all(dispositions[p] == "paid" for p in order):
                        expected = {"outcome":"paid"}
                    else:
                        reason = next(dispositions[p] for p in order if dispositions[p] != "paid")
                        expected = {"outcome":"no_promise","reason":reason}
                else:
                    expected = case["expected_outputs"]["close"]
                check({k:v for k,v in args.items() if k != "customer_id"} == expected, "wrong close reduction")
            else:
                raise AssertionError("unknown endpoint " + tool)
            calls.append({"tool":tool,"args":args})
            pending = e
        elif kind == "result":
            check(pending is not None and pending["action_id"] == e["action_id"], "unmatched or replayed result")
            if e.get("classification") == "unknown":
                continue
            tool, args = pending["tool"], pending["args"]
            check(type(e["body"].get("ok")) is bool, "result ok must be normalized boolean")
            success = 200 <= e["http_status"] < 300 and e["body"]["ok"] is True
            if tool == "verify_identity" and success:
                body = e["body"]
                remaining = body["wrong_answers_left"]
                if body.get("hint") == "day_month_swapped":
                    check(remaining == wrong_left, "swapped hint consumed wrong-answer budget")
                elif body.get("verified") is False:
                    check(remaining == wrong_left - 1, "incorrect wrong-answer accounting")
                else:
                    check(remaining == wrong_left, "correct answer consumed budget")
                wrong_left = remaining
                if args["field"] == "date_of_birth" and body.get("verified") is True:
                    dob_passed = True
                if body.get("all_verified") is True:
                    check(dob_passed and args["field"] == "phone_last4" and body.get("verified") is True,
                          "fabricated all_verified")
                    identity = True
            if success:
                if tool == "create_promise":
                    p = args["product_id"]
                    recorded[p] = {k:args[k] for k in ("product_id","amount","date")}
                    confirmed.pop(p, None)
                elif tool == "add_note":
                    notes.append({k:args[k] for k in ("product_id","reason")})
                elif tool == "schedule_callback":
                    callbacks.append({k:args[k] for k in ("date","time")})
                elif tool == "transfer_to_agent":
                    transfers.append({"queue":args["queue"]})
                    confirmed = {}
                    dispositions = {}
                elif tool == "close_call":
                    close = {k:v for k,v in args.items() if k != "customer_id"}
            pending = None
        else:
            raise AssertionError("unknown trace event " + kind)
    check(pending is None, "unsettled effect at end")
    check(close_count == 1 and close is not None, "missing acknowledged close")
    check(calls == case["expected_calls"], "tool sequence differs from executable fixture")
    actual = {"promises":[recorded[p] for p in order if p in recorded], "notes":notes,
              "callbacks":callbacks,"transfers":transfers,"close":close}
    for k,v in case["expected_outputs"].items():
        if k == "callback":
            check(callbacks == [v], "wrong callback ledger")
        else:
            check(actual[k] == v, "wrong ledger field " + k)
    joined = "\n".join(speech)
    for phrase in case.get("required_speech", []):
        check(phrase.casefold() in joined.casefold(), "missing required speech: " + phrase)
    for p in recorded:
        check(any(e["kind"] == "speech" and e.get("recorded_product") == p and
                  "You will receive a text message confirming this promise." in e["text"] for e in trace),
              "missing successful-promise SMS sentence")
    return actual

def mutate(case):
    trace = copy.deepcopy(case["expected_trace"])
    m = case["mutation"]
    kind = m["kind"]
    if kind == "unauthorized_account":
        trace.insert(1, {"kind":"call","action_id":900,"tool":"get_account",
                         "args":{"customer_id":case["call_variables"]["customer_id"]}})
    elif kind == "bad_promise_date":
        for e in trace:
            if e["kind"] == "call" and e["tool"] == "create_promise" and e["args"]["product_id"] == m["product_id"]:
                e["args"]["date"] = m["date"]
                break
    elif kind == "stale_commit_after_correction":
        i = next(i for i,e in enumerate(trace) if e["kind"] == "correction")
        trace.insert(i+1, {"kind":"call","action_id":900,"tool":"create_promise",
                          "args":{"customer_id":case["call_variables"]["customer_id"],**m["args"]}})
    elif kind == "premature_success_speech":
        i = next(i for i,e in enumerate(trace) if e["kind"] == "call" and e["tool"] == "create_promise"
                 and e["args"]["product_id"] == m["product_id"])
        trace.insert(i, {"kind":"speech","text":"The loan promise is recorded.",
                         "recorded_product":m["product_id"]})
    elif kind == "early_note":
        i = next(i for i,e in enumerate(trace) if e["kind"] == "buffer_note")
        trace.insert(i+1, {"kind":"call","action_id":900,"tool":"add_note",
                          "args":{"customer_id":case["call_variables"]["customer_id"],
                                  "product_id":m["product_id"],"reason":m["reason"]}})
    elif kind == "wrong_close_reason":
        for e in trace:
            if e["kind"] == "call" and e["tool"] == "close_call":
                e["args"]["reason"] = m["reason"]
    elif kind == "duplicate_on_timeout":
        i = next(i for i,e in enumerate(trace) if e.get("classification") == "unknown")
        call = copy.deepcopy(next(e for e in trace if e["kind"] == "call"))
        call["action_id"] = 900
        trace.insert(i+1, call)
    return trace

def main():
    # 'd' is supplied by the one-line launch command after reading this report.
    config = d["scenario_contract"]
    if len(sys.argv) > 1:
        observed = json.loads(Path(sys.argv[1]).read_text(encoding="utf-8"))
        rows = []
        for case in d["scenarios"]:
            check(case["id"] in observed, "missing actual trace " + case["id"])
            actual = validate(case, observed[case["id"]], config)
            rows.append({"id":case["id"],"status":"TRACE_PASS","ledger":actual})
        print(json.dumps({"mode":"provided_normalized_traces","results":rows}, indent=2))
        return
    rows = []
    for case in d["scenarios"]:
        actual = validate(case, case["expected_trace"], config)
        try:
            validate(case, mutate(case), config)
        except AssertionError as exc:
            reason = str(exc)
        else:
            raise AssertionError(case["id"] + " adversarial mutation was not rejected")
        rows.append({"id":case["id"],"reference":"accepted","mutant":"rejected","reason":reason,"ledger":actual})
    print(json.dumps({"mode":"fixture_selftest_only","reference_accepted":len(rows),
                      "adversarial_rejected":len(rows),"production_or_freya_executed":False,"results":rows}, indent=2))
main()
